local({
  ans <- coalesce(as.numeric(CPADHD00), as.numeric(DPADHD00), as.numeric(EPADHD00), as.numeric(FPADHD00))
  ans[!ans %in% 1:2] <- NA
  sweep <- match(.wave, c("sweep_3", "sweep_4", "sweep_5", "sweep_6"))
  prior <- stats::ave(seq_along(ans), participant_id, FUN = function(i) {
    vapply(
      i,
      function(r) {
        earlier <- i[!is.na(sweep[i]) & sweep[i] < sweep[r] & !is.na(ans[i])]
        if (is.na(sweep[r]) || length(earlier) == 0) {
          NA_real_
        } else {
          ans[earlier][which.max(sweep[earlier])]
        }
      },
      numeric(1)
    )
  })
  case_when(
    ans == 1 ~ "Currently diagnosed",
    ans == 2 ~ "Never diagnosed",
    .wave %in% c("sweep_5", "sweep_6") & prior == 1 ~ "Currently diagnosed",
    .default = NA_character_
  )
})

